insert into negocios (id, nombre, slug, categoria_oficial_id, municipio, vereda_id, direccion, latitud, longitud, descripcion_corta, descripcion, producto, telefono, whatsapp, email, representante_legal, nit, naturaleza_juridica, delegado, tiempo_constitucion, rut_camara_comercio, responsable_cdmb, novedad, tipo_negocio_verde, codigo_marca, anio_registro, cota_msnm, aplicacion_ficha_2025, observaciones, registro_nacional_turismo, uso_suelo, concesion_aguas, concesion_aguas_vencimiento, vertimientos, vertimientos_vencimiento, pueaa, pgris, pozo_septico, alcantarillado, ica, ica_vencimiento, invima, invima_vencimiento, certificado_tenencia_animales, buenas_practicas_agricolas, buenas_practicas_apicolas, registro_apicola, intervencion_cauce, capacidad_carga, sstt, canal_venta, exportacion, huella_carbono, fortalecimiento_tecnico, fortalecimiento_academico, fortalecimiento_financiero, internacionalizacion, certificaciones, posicionamiento_marca, beneficios_ventanilla, fortalezas_ambiental, fortalezas_social, fortalezas_economico, debilidades_ambiental, debilidades_social, debilidades_financiera, emprendimiento_verde, sello_marca, avalado, destacado, activo) values ('39d7984b-43ba-4084-8a67-3cd1569e0889', 'TOLVACAO', generar_slug_unico('TOLVACAO', '39d7984b-43ba-4084-8a67-3cd1569e0889'), (select id from categorias_oficiales where slug = 'bioproductos-servicios-sostenibles'), 'Rionegro', (select id from veredas where municipio = 'Rionegro' and slug = 'la-union'), 'VEREDA LA UNION FINCA LA ALSACIA', null, null, 'En nuestra empresa nos especializamos en la elaboración de productos saludables como gomas saludables, nibs de cacao cubiertos con miel y panela, chocolate…', 'En nuestra empresa nos especializamos en la elaboración de productos saludables como gomas saludables, nibs de cacao cubiertos con miel y panela, chocolate de mesa, vino, mermeladas, los cuales están hechos a base de baba de cacao (mucílago), cacao tostado y fruta. En este sentido, la idea de negocio surge como respuesta a la necesidad de dar un uso significativo al mucílago de cacao, el cual es considerado como residuo.', 'GOMAS DE MUCILAGO', '3133490199', null, 'reinaalexandra.19@gmail.com', 'JENNIFER ALEXANDRA CORZO REINA', '1098824690-6', 'Natural', null, '29 MESES', 'Camara de comercio', 'HEINER ORTIZ', 'ACTIVO', null, null, 2024, null, 'ACTUALIZO', 'Se realizo visita y se actualizo ficha de verificacion', null, 'NO', 'ACUEDUCTO VEREDAL', null, null, null, 'NO', 'NO', null, 'SI', 'Natural', null, 'NO', null, null, 'NO', null, null, null, null, 'NO', 'MIXTA', 'NO', 'NO', 'Se requiere para el fortalecimiento de la marca y Mejorar procesos de transformación', 'Participación en talleres técnicos (cursos SENA o Cámara de Comercio) sin embargo Requiere apoyo en contabilidad y finanzas.', 'Se requiere asesoría en costos, punto de equilibrio, y búsqueda de fondos o convocatorias', 'NO', null, 'En proceso, contamos con redes sociales y buscamos un empaque innovador para los productos.', null, 'Transformación de subproductos del cacao (mucílago) en productos con valor agregado (vino, gomitas). Modelo de economía circular: reducción de residuos orgánicos. Bajo uso de químicos o aditivos en el proceso productivo.', 'Vinculación con productores locales de cacao de Santander. Vinculación de mujeres campesinas en producción', 'Propuesta de valor diferenciada: productos funcionales, naturales, con origen sostenible. Participación en ferias locales y eventos (visibilidad inicial del emprendimiento). Enfoque hacia nichos de mercado en crecimiento (alimentación saludable, gourmet, vegano). Negocio registrado formalmente en Cámara de Comercio.', 'No se cuenta con plan formal de manejo ambiental. No se cuenta con un plan de Manejo básico de residuos sólidos.', 'No se realizan talleres comunitarios regulares o alianzas con colegios/veredas. Falta de una estrategia de relacionamiento comunitario y participación constante.', 'No se cuenta con presupuesto asignado para promoción ni diseño profesional de empaque o etiqueta. Poca visibilidad y reconocimiento de marca en el mercado regional. Falta de un plan de mercadeo estructurado (estrategia, canales, mensajes clave)', true, false, false, false, false);
